-- Uploaded files; see docs/STORAGE.md. Rows hold storage keys, not URLs, so files can move
-- between providers; URLs are built when a file is read.

CREATE TYPE file_status AS ENUM ('PENDING', 'READY');

CREATE TABLE files (
    -- The user whose folder the file is in, or -1 for community files.
    owner_id     BIGINT      NOT NULL CHECK (owner_id > 0 OR owner_id = -1),
    -- Random, generated by the backend; unique within the owner's folder.
    id           TEXT        NOT NULL,
    -- Storage provider holding the object: `local` or `s3`.
    backend      TEXT        NOT NULL,
    -- Object key within that provider.
    key          TEXT        NOT NULL,
    -- Sanitized client file name, only used for Content-Disposition.
    name         TEXT        NOT NULL,
    content_type TEXT        NOT NULL,
    -- Declared when the upload is issued; the stored object must match it.
    size         BIGINT      NOT NULL CHECK (size > 0),
    e_tag        TEXT,
    -- PENDING until the bytes are uploaded and verified.
    status       file_status NOT NULL DEFAULT 'PENDING',
    uploaded_by  BIGINT      REFERENCES users (id) ON DELETE SET NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    completed_at TIMESTAMPTZ,
    PRIMARY KEY (owner_id, id)
);

-- Upload rate limit.
CREATE INDEX files_uploader_idx ON files (uploaded_by, created_at DESC);
-- Sweeping abandoned uploads.
CREATE INDEX files_pending_idx ON files (created_at) WHERE status = 'PENDING';
